quotes.text:
&.icon-only {
  background-position: center;
  /* 2px at the end for the border. */
  block-size: calc(var(--button-padding) * 2 + var(--icon-size) + 2px);
  padding: 0;
  aspect-ratio: 1;

  &.button-round {
    --button-border-radius: 50%;
  }

&.modal-close-button {
  display: inline-flex;
  justify-content: center;
  align-items: center;
}

/* Header style */
header {
  text-align: center;

  & #close {
    position: absolute;
    inset-inline-end: 6px;
    inset-block-start: 6px;
    z-index: 1;
  }
